def finish() -> Any:
            try:
                ubatch_contexts[0].cpu_wait_event.set()
                for thread in threads:
                    thread.join()
            finally:
                self._pending_finish = None
                stack.close()

            if errors:
                failed = next(iter(errors))
                raise RuntimeError(
                    f"Microbatch {failed} of {self.num_ubatches} failed"
                ) from errors[failed]
            return merge_ubatch_outputs([outputs[i] for i in range(self.num_ubatches)])

def _pack_strided_descs(
        strided_descs: list[tuple[int, int, int, int, int]],
    ) -> np.ndarray:
        """Pack (addr, len, dev_id, stride, count) rows into an Nx5 uint64 array.

        Each row describes `count` blocks of `len` bytes whose starts are
        `stride` bytes apart; NIXL >= 1.5 prepares this layout directly.
        """
        return np.array(strided_descs, dtype=np.uint64).reshape(-1, 5)

def get_num_new_matched_tokens(
        self,
        request: "Request",
        num_computed_tokens: int,
    ) -> tuple[int | None, bool]:
        to_return = (0, False)
        for i, c in enumerate(self._connectors):
            toks, load_async = c.get_num_new_matched_tokens(
                request, num_computed_tokens
            )
            # If there is a connector still looking up the matches,
            # we return None to indicate that we are not done yet.
            if toks is None:
                return (None, False)
            # The first connector that has new matched tokens will be assigned
            # to this request.
            if to_return[0] == 0 and toks > 0:
                self._requests_to_connector[request.request_id] = i
                to_return = (toks, load_async)
        return to_return

